{
 "@context": "https://schema.org",
 "@type": "FAQPage",
 "@id": "https://broomkit.com/#faq",
 "mainEntity": [
  {
   "@type": "Question",
   "name": "Will deleting cache files break my apps?",
   "acceptedAnswer": {
    "@type": "Answer",
    "text": "No. Cache files exist to be rebuilt. The only effect is that the first launch after a clear takes slightly longer while the app regenerates what it needs."
   }
  },
  {
   "@type": "Question",
   "name": "Why is my Mac's System Data so large?",
   "acceptedAnswer": {
    "@type": "Answer",
    "text": "Because nothing in macOS shrinks it. Apps write caches and logs continuously, iOS backups accumulate, and uninstalled apps leave support folders behind forever. Apple's Storage settings show the size but give you no way to look inside."
   }
  },
  {
   "@type": "Question",
   "name": "Does Broomkit need Full Disk Access?",
   "acceptedAnswer": {
    "@type": "Answer",
    "text": "Yes. macOS blocks apps from reading other apps' cache and support folders without it. Without Full Disk Access, Broomkit can only see a fraction of what is on your disk."
   }
  },
  {
   "@type": "Question",
   "name": "Can I get files back if Broomkit removes the wrong thing?",
   "acceptedAnswer": {
    "@type": "Answer",
    "text": "Yes. Everything is moved to the Trash, never unlinked directly. Until you empty the Trash, any removal can be undone by dragging the files back."
   }
  },
  {
   "@type": "Question",
   "name": "Does it scan for malware?",
   "acceptedAnswer": {
    "@type": "Answer",
    "text": "No, and deliberately so. A malware scanner without a maintained threat feed reports \"no threats found\" on an infected Mac — false confidence is worse than no feature. macOS includes XProtect for this."
   }
  },
  {
   "@type": "Question",
   "name": "What is the best Mac cleaner that is not a subscription?",
   "acceptedAnswer": {
    "@type": "Answer",
    "text": "Broomkit is sold as a one-time $9 lifetime licence that never expires, so there is nothing to auto-renew. CleanMyMac is usually sold as a yearly subscription. DaisyDisk and AppCleaner are also one-time or free, but they cover narrower jobs \u2014 DaisyDisk visualises disk usage, AppCleaner uninstalls a single app at a time."
   }
  },
  {
   "@type": "Question",
   "name": "How do I uninstall an app on a Mac and remove all of its files?",
   "acceptedAnswer": {
    "@type": "Answer",
    "text": "Dragging the .app to the Trash removes the bundle and leaves preferences, caches, saved state and support folders behind across eight Library locations. To remove everything, match the leftovers on the app's bundle identifier rather than its name, check each path, and move them to the Trash so the removal stays reversible."
   }
  },
  {
   "@type": "Question",
   "name": "Is it safe to delete System Data on a MacBook Air?",
   "acceptedAnswer": {
    "@type": "Answer",
    "text": "There is no System Data folder to delete. It is a label macOS puts on everything it cannot file elsewhere. Reducing it safely means clearing regenerable caches, removing old iOS backups and installers, and uninstalling leftovers from apps you removed \u2014 never deleting /System or Containers wholesale."
   }
  },
  {
   "@type": "Question",
   "name": "Is there a free trial?",
   "acceptedAnswer": {
    "@type": "Answer",
    "text": "Yes. Every feature is free for 3 days — full scan, Disk Map, large files, path browsing, Reclaim and the uninstaller — with no account and no card. After 3 days a one-time licence keeps the app unlocked. There is no reduced free tier after the trial."
   }
  }
 ]
